#include <vector>

class Solution {
    int R, C;
    const int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    bool dfs(int r, int c, int pr, int pc, char ch, const std::vector<std::vector<char>>& grid, std::vector<std::vector<bool>>& visited) {
        visited[r][c] = true;
        for (int d = 0; d < 4; ++d) {
            int nr = r + dirs[d][0], nc = c + dirs[d][1];
            if (nr >= 0 && nr < R && nc >= 0 && nc < C && grid[nr][nc] == ch) {
                if (nr == pr && nc == pc) continue;
                if (visited[nr][nc]) return true;
                if (dfs(nr, nc, r, c, ch, grid, visited)) return true;
            }
        }
        return false;
    }
public:
    bool containsCycle(std::vector<std::vector<char>>& grid) {
        R = grid.size(); C = grid[0].size();
        std::vector<std::vector<bool>> visited(R, std::vector<bool>(C, false));
        for (int r = 0; r < R; ++r) {
            for (int c = 0; c < C; ++c) {
                if (!visited[r][c]) {
                    if (dfs(r, c, -1, -1, grid[r][c], grid, visited)) return true;
                }
            }
        }
        return false;
    }
};

class Solution {
    int R, C;
    int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    private boolean dfs(int r, int c, int pr, int pc, char ch, char[][] grid, boolean[][] visited) {
        visited[r][c] = true;
        for (int[] d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr >= 0 && nr < R && nc >= 0 && nc < C && grid[nr][nc] == ch) {
                if (nr == pr && nc == pc) continue;
                if (visited[nr][nc]) return true;
                if (dfs(nr, nc, r, c, ch, grid, visited)) return true;
            }
        }
        return false;
    }
    public boolean containsCycle(char[][] grid) {
        R = grid.length; C = grid[0].length;
        boolean[][] visited = new boolean[R][C];
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                if (!visited[r][c]) {
                    if (dfs(r, c, -1, -1, grid[r][c], grid, visited)) return true;
                }
            }
        }
        return false;
    }
}

var containsCycle = function(grid) {
    const R = grid.length, C = grid[0].length;
    const visited = Array.from({ length: R }, () => new Uint8Array(C));
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    function dfs(r, c, pr, pc, ch) {
        visited[r][c] = 1;
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < R && nc >= 0 && nc < C && grid[nr][nc] === ch) {
                if (nr === pr && nc === pc) continue;
                if (visited[nr][nc]) return true;
                if (dfs(nr, nc, r, c, ch)) return true;
            }
        }
        return false;
    }
    for (let r = 0; r < R; r++) {
        for (let c = 0; c < C; c++) {
            if (!visited[r][c]) {
                if (dfs(r, c, -1, -1, grid[r][c])) return true;
            }
        }
    }
    return false;
};
